/** Generates docs/GRAMMAR.md from the live grammar engine (so docs never drift from code). */
import { writeFileSync } from 'node:fs';
import { A, G0, G1, GFin, GF, showG, detectLR } from '../js/grammar.js';

const set = (s) => '{ ' + [...s].join(', ') + ' }';
const block = (...l) => ['```', ...l, '```', ''];
const md = [
  '# Grammar report (generated by `npm run docs`)',
  '',
  '## Original CFG (G0)',
  ...block(showG(G0)),
  '## Left recursion detected',
  ...block(...detectLR(G0)),
  '## After left-recursion removal (G1, used by the parser)',
  ...block(showG(G1)),
  '## Left factoring example',
  ...block(showG(GFin)),
  'Factored:',
  ...block(showG(GF)),
  '## FIRST sets',
  ...block(...A.g.order.map((a) => `FIRST(${a}) = ${set(A.F[a])}`)),
  '## FOLLOW sets',
  ...block(...A.g.order.map((a) => `FOLLOW(${a}) = ${set(A.Fo[a])}`)),
  `LL(1) table conflicts: **${A.conf.length}**`,
  '',
].join('\n');
writeFileSync(new URL('../docs/GRAMMAR.md', import.meta.url), md);
console.log('docs/GRAMMAR.md written');
